export const BODY: string = "\n<p>تصویر کولاج بنانا مختصر کام ہے: چند تصویریں چنیں، لے آؤٹ چنیں، انہیں ترتیب دیں اور ایک تصویر برآمد کریں۔ یہ رہنما ہر مرحلہ ترتیب سے بتاتا ہے، تصویریں چننے سے لے کر تیار کولاج شیئر کرنے تک۔</p>\n<p>شروع کرنے سے پہلے آپ کو صرف ایک چیز چاہیے: وہ تصویریں جنہیں آپ جوڑنا چاہتے ہیں۔ ملتی جلتی روشنی والی چار سے نو مضبوط تصویریں بہترین کولاج بناتی ہیں۔ ایک سفر، ایک تقریب یا ایک مصنوعات کی رینج کی تصویروں کا سیٹ بے ترتیب مرکب سے بہتر کام کرتا ہے۔</p>\n<p><a href=\"/ur/tasveer-collage-maker/\">تصویر کولاج میکر</a> کام آپ کے براؤزر میں کرتا ہے۔ کچھ بھی سرور پر اپ لوڈ نہیں ہوتا، کوئی اکاؤنٹ نہیں، اور برآمد مفت ہے۔ نیچے کے مراحل پر عمل کریں اور چند منٹ میں آپ کے پاس تیار کولاج ہو گا۔</p>\n<h2 id=\"step-1-choose-your-photos\">مرحلہ 1: اپنی تصویریں چنیں</h2>\n<p>وہ تصویریں چنیں جو ایک ساتھ ہوں۔ کولاج چھوٹی کہانی بتاتا ہے، اس لیے تصویروں کو موضوع شیئر کرنا چاہیے: سفر، سالگرہ، مصنوعات کی رینج یا خاندانی اجتماع۔ ایک تقریب کی تصویریں مجموعہ لگتی ہیں؛ پانچ تقریبات کی تصویریں بے ترتیب ڈھیر لگتی ہیں۔</p>\n<p>چار سے نو تصویریں چنیں۔ چار 2 بہ 2 گرڈ کو صاف بھرتی ہیں، اور نو 3 بہ 3 گرڈ کو بھرتے ہیں۔ چار سے کم خالی سیل چھوڑتی ہیں، اور نو سے زیادہ ہر تصویر کو لطف اٹھانے کے لیے بہت چھوٹا بناتا ہے۔ کولاج میں مقدار پر معیار غالب ہے۔</p>\n<p>ملتی جلتی روشنی اور رنگ والی تصویریں چنیں۔ وہ سیٹ جہاں ایک تصویر گہری اور دھندلی ہو، آنکھ کو کمزور تصویر کی طرف کھینچتا ہے، جبکہ مستقل روشنی والا سیٹ جان بوجھ کر بنایا گیا مجموعہ لگتا ہے۔ اگر ایک تصویر باقی سے کہیں گہری ہو تو شروع کرنے سے پہلے اسے روشن کریں یا اسے چھوڑ دیں۔</p>\n<h2 id=\"step-2-upload-the-photos\">مرحلہ 2: تصویریں اپ لوڈ کریں</h2>\n<p>کولاج میکر کھولیں اور اپنی تصویریں اپ لوڈ والے حصے پر گھسیٹ دیں، یا اپنے آلے سے چننے کے لیے اس پر کلک کریں۔ آپ انہیں ایک ساتھ اپ لوڈ کر سکتے ہیں، اور ٹول انہیں آپ کی چنی ہوئی ترتیب میں گرڈ میں رکھے گا۔</p>\n<p>ٹول 20 MB تک JPG، PNG، WebP، HEIC، GIF، BMP اور SVG فائلیں قبول کرتا ہے۔ فون کی تصویریں، اسکرین شاٹ اور گرافکس سب کام کرتے ہیں، اور ایک کولاج میں فارمیٹ کا مرکب ٹھیک ہے۔ آئی فون کی HEIC تصویر کسی بھی دوسری فائل کی طرح اپ لوڈ ہوتی ہے۔</p>\n<p>پانچ یا زیادہ تصویریں ڈالنے سے 3 بہ 3 گرڈ خود بخود چن لیا جاتا ہے، جبکہ چار یا کم سے 2 بہ 2 گرڈ خود بخود چن لیا جاتا ہے۔ اگر آپ گرڈ کے سیل سے کم تصویریں اپ لوڈ کریں تو خالی سیل مزید تصویروں کا انتظار کرتے ہیں، اور آپ انہیں بعد میں شامل کر سکتے ہیں۔</p>\n<h2 id=\"step-3-pick-a-layout\">مرحلہ 3: لے آؤٹ چنیں</h2>\n<p>گرڈ یا پٹی لے آؤٹ چنیں۔ 2 بہ 2 گرڈ چار تصویروں کو سوٹ کرتا ہے، 3 بہ 3 گرڈ نو کو سوٹ کرتا ہے، عمودی پٹی اوپر سے نیچے پڑھی جانے والی ترتیب کو سوٹ کرتی ہے، اور افقی پٹی بائیں سے دائیں پڑھی جانے والی ترتیب کو سوٹ کرتی ہے۔</p>\n<p>گرڈ ان سیٹوں کو سوٹ کرتے ہیں جہاں ہر تصویر یکساں اہم ہے: سفر، تقریب یا مصنوعات کی رینج۔ مربع شکل فیڈ اور لسٹنگ کو سوٹ کرتی ہے، اور برابر سیل ہر تصویر کو ایک جیسا وزن دیتے ہیں۔</p>\n<p>پٹیاں ترتیب اور موازنہ کو سوٹ کرتی ہیں۔ عمودی پٹی کہانی کی طرح پڑھتی ہے، جو ترتیب میں دن کو سوٹ کرتی ہے۔ افقی پٹی ٹائم لائن کی طرح پڑھتی ہے، جو پہلے اور بعد یا لمحوں کے پینوراما کو سوٹ کرتی ہے۔</p>\n<h2 id=\"step-4-arrange-the-photos\">مرحلہ 4: تصویریں ترتیب دیں</h2>\n<p>ڈیسک ٹاپ پر ایک تصویر کو دوسرے سیل پر گھسیٹ کر انہیں بدلیں، یا فون پر منتخب کرنے کے لیے ٹیپ کریں اور بدلنے کے لیے دوبارہ ٹیپ کریں۔ تبدیلی فوراً ہوتی ہے، اور آپ برآمد سے پہلے جتنی بار چاہیں دوبارہ ترتیب دے سکتے ہیں۔</p>\n<p>ہیرو تصویر کو سب سے نمایاں سیل میں رکھیں۔ 2 بہ 2 گرڈ میں وہ اوپر بائیں سیل ہے، جسے آنکھ پہلے دیکھتی ہے۔ 3 بہ 3 گرڈ میں مرکز سیل آنکھ کھینچتا ہے، اس لیے ہیرو وہاں یا اوپر بائیں ہونا چاہیے۔</p>\n<p>گرڈ میں روشنی اور تاریکی متوازن رکھیں۔ ایک گہری تصویر کے ساتھ دوسری گہری تصویر بھاری کونہ بناتی ہے، جبکہ ہلکی تصویر کے ساتھ گہری تصویر کولاج کو متوازن کرتی ہے۔ روشن اور گہری تصویروں کو جما کرنے کی بجائے یکساں پھیلائیں۔</p>\n<h2 id=\"step-5-feature-a-photo\">مرحلہ 5: تصویر کو نمایاں کریں</h2>\n<p>تقسیم لکیریں گھسیٹ کر ہیرو تصویر کو باقی سے بڑا کریں۔ تقسیم لکیر گھسیٹنے سے ہیرو سیل بڑا اور اس کے پڑوسی چھوٹے ہو جاتے ہیں، جو کولاج کو چپٹے گرڈ کی بجائے مرکز اور درجہ بندی دیتا ہے۔</p>\n<p>نمایاں تصویر کو موضوع کے ساتھ ساتھ معیار کے حساب سے بھی چنیں۔ ہیرو سیٹ کی تیز ترین، روشن ترین تصویر ہونی چاہیے، کیونکہ کمزور تصویر کو بڑا کرنے سے صرف اس کی خامیوں پر توجہ پڑتی ہے۔ بڑی کی گئی مضبوط تصویر جان بوجھ کر بنائی لگتی ہے؛ بڑی کی گئی کمزور تصویر غلطی لگتی ہے۔</p>\n<p>نمایاں ایک تصویر تک رکھیں۔ دو بڑے سیل ایک دوسرے سے مقابلہ کرتے ہیں اور درجہ بندی گر جاتی ہے، اس لیے ایک سیل کو باقی سے واضح طور پر بڑا کریں اور دوسرے برابر چھوڑ دیں۔ ایک نمایاں وہ قاعدہ ہے جو کولاج کو ایک نظر میں پڑھنے کے قابل بناتا ہے۔</p>\n<h2 id=\"step-6-adjust-gaps-and-corners\">مرحلہ 6: خالی جگہ اور کونے ایڈجسٹ کریں</h2>\n<p>سیل کے درمیان خالی جگہ طے کریں۔ صفر خالی جگہ بغیر سرحد والا ہموار کولاج بناتی ہے، جہاں تصویریں چھوتی ہیں اور ایک مسلسل تصویر بناتی ہیں۔ نظر آنے والی خالی جگہ تصویروں کو الگ فریموں میں تقسیم کرتی ہے، جو اسکریپ بک یا گیلری شکل کو سوٹ کرتی ہے۔</p>\n<p>سیل کے لیے کونے کا رداس طے کریں۔ چھوٹا رداس کولاج کو نرم کرتا ہے اور سوشل پوسٹ کو سوٹ کرتا ہے، جبکہ مربع کونے رسمی لگتے ہیں اور پرنٹ اور لسٹنگ کو سوٹ کرتے ہیں۔ بڑا رداس ہر سیل کو گول ٹائل میں بدل دیتا ہے، جو کھیل کود والے ڈیزائن کو سوٹ کرتا ہے۔</p>\n<p>خالی جگہ اور کونے کا رداس آزاد ہیں، اس لیے آپ انہیں آزادانہ جوڑ سکتے ہیں۔ مربع کونوں والی چوڑی خالی جگہ گیلری دیوار لگتی ہے، جبکہ گول کونوں والی تنگ خالی جگہ ایپ لگتی ہے۔ جوڑ کولاج کا مزاج طے کرتا ہے۔</p>\n<h2 id=\"step-7-set-the-background\">مرحلہ 7: پس منظر طے کریں</h2>\n<p>فوری پری سیٹ سے پس منظر رنگ چنیں۔ سفید پہلے سے طے شدہ اور محفوظ ترین انتخاب ہے: یہ کولاج کو صاف رکھتا ہے، کسی بھی فیڈ یا صفحے سے میل کھاتا ہے، اور تصویروں کو تصویر میں واحد رنگ بناتا ہے۔</p>\n<p>برانڈ رنگ کولاج کو ڈیزائن شدہ گرافک میں بدل دیتا ہے۔ خالی جگہوں میں رنگ کولاج کو مہم سے جوڑتا ہے، اور ایک ہی رنگ میں کولاج کا سیٹ پہچانا جانے والا سلسلہ بناتا ہے۔ اسے اس وقت استعمال کریں جب کولاج مجموعہ جتنا ہی اشتہار ہو۔</p>\n<p>سیل میں رکھے شفاف PNG اسٹیکر اپنے پیچھے پس منظر رنگ دکھاتے ہیں۔ سفید پس منظر پر اسٹیکر صاف کٹ آؤٹ لگتا ہے، جبکہ رنگ والے پس منظر پر اسٹیکر پیچھے کے رنگ سے رنگت لیتا ہے۔ برآمد سے پہلے اسٹیکر پس منظر کے خلاف جانچیں۔</p>\n<h2 id=\"step-8-choose-the-canvas-size\">مرحلہ 8: کینوس سائز چنیں</h2>\n<p>منزل کے لیے کینوس سائز اور تناسب چنیں۔ مربع فیڈ، لسٹنگ اور تھمب نیل کو سوٹ کرتا ہے۔ پورٹریٹ کہانیوں اور فون وال پیپر کو سوٹ کرتا ہے۔ چوڑا بینر اور ہیڈر کو سوٹ کرتا ہے۔ ٹول ہر شکل کے لیے فوری پری سیٹ دیتا ہے۔</p>\n<p>برآمد ریزولوشن 4000 پکسل تک جاتی ہے، جو پرنٹ کے لیے کافی بڑی ہے۔ بڑی برآمد چنیں جب کولاج پرنٹ ہو سکتا ہے، اور معتدل جب وہ صرف آن لائن پوسٹ ہو گا۔ آپ بعد میں ہمیشہ سائز کم کر سکتے ہیں، مگر پکسل واپس نہیں لا سکتے۔</p>\n<p>چنے ہوئے تناسب پر پیش نظارہ جانچیں۔ مربع کے طور پر متوازن لگنے والا کولاج پورٹریٹ کے طور پر کھینچا ہوا لگ سکتا ہے، کیونکہ سیل شکل بدلتے ہیں۔ تناسب بدلنے کے بعد ترتیب ایڈجسٹ کریں، کیونکہ ایک شکل کے لیے بہترین لے آؤٹ دوسری کو سوٹ نہ کرے۔</p>\n<h2 id=\"step-9-preview-the-collage\">مرحلہ 9: کولاج کا پیش نظارہ دیکھیں</h2>\n<p>برآمد سے پہلے مکمل پیش نظارہ دیکھیں۔ جانچیں کہ ہر تصویر درست سیل میں ہے، ہیرو تصویر نمایاں ہے، خالی جگہیں برابر ہیں، اور پس منظر رنگ آپ کی مرضی جیسا لگتا ہے۔ مکمل سائز پر پیش نظارہ وہ تفصیل دکھاتا ہے جو تھمب نیل چھپاتا ہے۔</p>\n<p>ہر سیل میں خراب کراپ جانچیں۔ Cover فٹ چہرہ، مصنوعات لیبل، یا متن کی لکیر کو تصویر کے کنارے پر کاٹ سکتا ہے۔ اس سیل کے لیے فٹ Contain پر بدلیں جہاں کراپ نقصان دے، اور اس کے ساتھ آنے والی سرحد قبول کریں۔</p>\n<p>اگر کولاج سوشل میڈیا کے لیے ہے تو اسے اپنے فون پر دیکھیں۔ ڈیسک ٹاپ مانیٹر پر ہلکا لگنے والا خالی جگہ رنگ فون اسکرین پر بلند لگ سکتا ہے، اور بڑے پر متوازن لگنے والا کولاج چھوٹے پر مصروف لگ سکتا ہے۔ فون وہ ہے جہاں سامعین اسے دیکھتے ہیں۔</p>\n<h2 id=\"step-10-export-and-share\">مرحلہ 10: برآمد کریں اور شیئر کریں</h2>\n<p>برآمد فارمیٹ چنیں۔ JPG تصویروں اور کسی بھی کولاج کو سوٹ کرتا ہے جہاں چھوٹی فائل اہم ہو، جیسے سوشل پوسٹ۔ PNG تیز متن، چپٹے رنگ، یا شفافیت والے کولاج کو سوٹ کرتا ہے جو برآمد میں بچنی چاہیے۔</p>\n<p>ڈاؤن لوڈ پر کلک کریں اور تیار کولاج آپ کے آلے پر محفوظ ہو جاتا ہے۔ فائل نام کولاج ترتیبات ظاہر کرتا ہے، اس لیے آپ کئی ورژن برآمد کرنے پر انہیں الگ کر سکتے ہیں۔ شیئر کرنے سے پہلے فائل کھولیں اور اسے ایک بار اور دیکھیں۔</p>\n<p>کولاج کو ایک تصویر کے طور پر شیئر کریں: اسے سوشل فیڈ میں اپ لوڈ کریں، پیغام سے منسلک کریں، یا لسٹنگ میں شامل کریں۔ کولاج ایک فائل ہے، اس لیے وہ کسی بھی دوسری تصویر کی طرح پوسٹ ہوتی ہے، اور اس کے اندر کی تصویریں فائل کے ساتھ ہر جگہ سفر کرتی ہیں۔</p>\n<h2 id=\"collages-for-print\">پرنٹ کے لیے کولاج</h2>\n<p>پرنٹ کے لیے کولاج کو بڑی برآمد چاہیے۔ زیادہ سے زیادہ ریزولوشن چنیں، 4000 پکسل تک، تاکہ پرنٹ آپ کے مطلوبہ سائز پر تیز رہے۔ سوشل میڈیا کے لیے برآمد شدہ کولاج بڑے سائز پر خراب پرنٹ ہوتا ہے، کیونکہ پکسل موجود نہیں۔</p>\n<p>تیز ترین پرنٹ کے لیے PNG چنیں، یا تصویری پرنٹ کے لیے اعلیٰ کوالٹی JPG چنیں۔ PNG کنارے اور متن صاف رکھتا ہے، جبکہ JPG تصویروں کو مؤثر طریقے سے کمپریس کرتا ہے۔ بڑے برآمد سائز پر دونوں کام کرتے ہیں؛ انتخاب اس پر منحصر ہے کہ کولاج گرافک ہے یا تصویری۔</p>\n<p>پہلو تناسب کو کاغذ یا فریم سائز سے جانچیں۔ مربع کولاج مربع فریم میں فٹ ہوتا ہے، جبکہ پورٹریٹ کولاج معیاری تصویر پرنٹ میں فٹ ہوتا ہے۔ بے میل مطلب ہے پرنٹ کراپ کرنا یا سفید سرحدوں کے ساتھ رہنا، اس لیے برآمد سے پہلے تناسب ملائیں۔</p>\n<h2 id=\"fixing-a-collage-that-looks-off\">غلط لگنے والا کولاج درست کرنا</h2>\n<p>غلط لگنے والے کولاج میں عام طور پر چار مسائل میں سے ایک ہوتا ہے: کمزور تصویر، خراب کراپ، غیر متوازن ترتیب، یا خالی جگہ رنگ جو تصویروں سے لڑتا ہے۔ انہیں اس ترتیب سے درست کریں، تصویروں سے شروع کریں۔</p>\n<p>پہلے کمزور ترین تصویر بدلیں۔ گہری، دھندلی یا غیر متعلق تصویر چاہے جہاں بھی ہو، آنکھ کھینچتی ہے، اور کوئی ترتیب اسے چھپا نہیں سکتی۔ اسے اسی سیٹ کی مضبوط تصویر سے بدلیں، یا اس کے بغیر چھوٹے گرڈ پر جائیں۔</p>\n<p>اگلا، کراپ جانچیں۔ سیل کے کنارے پر کٹا ہوا چہرہ یا فٹ سے دبا ہوا موضوع سیل کو خراب کرتا ہے۔ اس سیل کے لیے فٹ Contain پر بدلیں، یا اس کے لیے مختلف تصویر چنیں، اور کولاج فوراً بہتر ہو جاتا ہے۔</p>\n<h2 id=\"quick-reference\">فوری حوالہ: کولاج چیک لسٹ</h2>\n<p>ملتی جلتی روشنی والی چار سے نو مضبوط تصویریں چنیں، انہیں اپ لوڈ کریں، اور گرڈ یا پٹی چنیں۔ گھسیٹ کر یا ٹیپ کر کے بدل کر ترتیب دیں، ہیرو تصویر بڑی کریں، اور خالی جگہیں، کونے اور پس منظر طے کریں۔</p>\n<p>منزل کے لیے کینوس تناسب چنیں، تصویروں کے لیے JPG اور گرافکس کے لیے PNG برآمد کریں، اور ہر سیل کو مکمل سائز اور تھمب نیل سائز پر خراب کراپ کے لیے جانچیں۔ بعد میں دوبارہ بنانے کے لیے ماخذ تصویریں رکھیں۔</p>\n<p>مکمل رہنما کے لیے <a href=\"/ur/blog/tasveer-collage-maker-rehnumai/\">Photo Collage Maker: Complete Guide</a> پڑھیں، اور لے آؤٹ خیالات کے لیے <a href=\"/ur/blog/collage-layouts-grids-mood-boards/\">Collage Layouts: Grids, Mood Boards and Stories</a> دیکھیں۔ اپنا کولاج <a href=\"/ur/tasveer-collage-maker/\">تصویر کولاج میکر</a> سے بنائیں۔</p>\n";

